async loadZhTwScriptStore() {
  this.zhTwScriptStore = null;
  try {
    const app = this.plugin.app;
    const id = app.plugins?.plugins?.i18n?.sourceManager?.getActiveSourceId("obsidian-excalidraw-plugin");
    if (typeof id !== "string" || !/^[\w-]+$/.test(id)) return;
    const file = app.vault.configDir + "/plugins/i18n/translations/" + id + ".json";
    const pack = JSON.parse(await app.vault.adapter.read(file));
    if (pack.metadata?.plugin !== "obsidian-excalidraw-plugin" || pack.metadata.language !== "zh-tw") return;
    const rows = pack.dict?.["main.js"]?.ast;
    if (!Array.isArray(rows)) return;
    const text = new Map();
    for (const row of rows) {
      if (typeof row?.name !== "string" || !row.name.startsWith("script-store:") ||
          typeof row.source !== "string" || !row.source.startsWith("【社群指令碼｜") ||
          typeof row.target !== "string" || !row.target.trim() || row.target === row.source) continue;
      text.set(row.name, [row.source.slice(row.source.indexOf("\n") + 1), row.target]);
    }
    this.zhTwScriptStore = text;
  } catch {}
}
getZhTwScriptText(kind, key, original) {
  const row = this.zhTwScriptStore?.get("script-store:" + kind + ":" + key);
  return row?.[0] === original ? row[1] : original;
}
getZhTwTitle(entry) {
  const name = this.getZhTwScriptText("name", entry.file, entry.name);
  return name === entry.name ? entry.name : name + "（" + entry.name + "）";
}
getZhTwCategory(name) {
  return this.getZhTwScriptText("category", name, name);
}
getZhTwDescriptionHtml(entry) {
  return this.getZhTwScriptText("description", entry.file, entry.descriptionHtml);
}
async loadStore(){try{const t=await e.request({url:Lg});this.catalog=Wg(t),await this.loadZhTwScriptStore?.(),await this.refreshInstallStates(),this.renderStore()}

getDescription(e, localized = false) {
  const key = localized ? "zh-tw:" + e.file : e.file;
  const cached = this.descriptionText.get(key);
  if (cached !== undefined) return cached;
  const html = localized ? this.getZhTwDescriptionHtml?.(e) ?? e.descriptionHtml : e.descriptionHtml;
  const text = (Wt(html).textContent ?? "").replace(/\s+/g," ").trim();
  this.descriptionText.set(key, text);
  return text;
}
